section.sourcecode:
void codel_queue_t::enqueue(packet_t* pkt)
{
    pkt->tstamp = clock();
    queue_t::enqueue(pkt);
}

packet_t* CoDelQueue::dequeue()
{
    time_t now = clock();
    dodequeue_result r = dodequeue(now);
    uint32_t delta;

    if (dropping_) {
        if (! r.ok_to_drop) {
            // 滞留時間がTARGETを下回った - ドロップ状態から抜ける
            dropping_ = false;
        }
        // 次のドロップの時刻。現在のパケットをドロップし、次を
        // デキューする。デキューによってドロップ状態から抜けな
        // ければ、次のドロップをスケジュールする。バックログが
        // 大きいとドロップ率が非常に高くなり、次のドロップを
        // すぐに行うべき場合があるため、'while'ループにしている。
        while (now >= drop_next_ && dropping_) {
            drop(r.p);
            ++count_;
            r = dodequeue(now);
            if (! r.ok_to_drop) {
                // ドロップ状態から抜ける
                dropping_ = false;
            } else {
                // 次のドロップをスケジュールする。
                drop_next_ = control_law(drop_next_, count_);
            }
        }
    // ここに来た場合はドロップ状態ではない。dodequeueが'ok_to_drop'を
    // 返したことは、滞留時間が'INTERVAL'の間'TARGET'を上回って
    // いたことを意味するので、ドロップ状態に入る。
    } else if (r.ok_to_drop) {
        drop(r.p);
        r = dodequeue(now);
        dropping_ = true;

        // 最小値が前回TARGETを下回ってから間もなく再び
        // 上回った場合は、前回のサイクルでキューを制御した
        // ドロップ率が、今回キューを制御するための良い
        // 出発点であると仮定する。（'drop_next'は最後の
        // ドロップの時刻から最大でも'INTERVAL'後なので、
        // 'now - drop_next'は最後のドロップから現在までの
        // 時間の良い近似になる。）実装によってここは少し
        // 異なる。これはLinux版であり、より広く展開され、
        // テストされている。
        delta = count_ - lastcount_;
        count_ = 1;
        if ((delta > 1) && (now - drop_next_ < 16*INTERVAL))
            count_ = delta;

        drop_next_ = control_law(now, count_);
        lastcount_ = count_;
    }
    return (r.p);
}

time_t codel_queue_t::control_law(time_t t, uint32_t count)
{
    return t + INTERVAL / sqrt(count);
}

typedef struct {
    packet_t* p;
    flag_t ok_to_drop;
} dodequeue_result;

dodequeue_result codel_queue_t::dodequeue(time_t now)
{
    dodequeue_result r = { queue_t::dequeue(), false };
    if (r.p == NULL) {
        // キューが空 - TARGETを上回っているはずがない
        first_above_time_ = 0;
        return r;
    }

    // 広範囲の帯域幅をカバーするために、CoDelは2つの異なる
    // AQMを並行して実行する。1つは滞留時間に基づくもので、
    // MTUサイズのパケットを送信する時間がTARGET未満のときに
    // 効果を発揮する。下の"if"の1つ目の項がこれを行う。
    // もう1つはバックログに基づくもので、MTUサイズの
    // パケットを送信する時間がTARGET以上（>=）のときに
    // 効果を発揮する。ここでの目標は、キューが典型的な
    // 到着間隔（MTUサイズのパケットが、そのようなパケットを
    // ボトルネックで送信するのにかかる時間の間隔を空けて
    // 到着する）の間に到着する量よりも小さくならないように
    // することで、出力リンクの利用率を高く保つことである。
    // "if"の2つ目の項がこれを行う。
    time_t sojourn_time = now - r.p->tstamp;
    if (sojourn_time_ < TARGET || bytes() <= maxpacket_) {
        // 下回った - 少なくともINTERVALの間は下回ったままとする
        first_above_time_ = 0;
    } else {
        if (first_above_time_ == 0) {
            // 下回っていた状態から上回ったところ。first_above_timeに
            // まだ上回っていれば、ドロップしてよいと返す。
            first_above_time_ = now + INTERVAL;
        } else if (now >= first_above_time_) {
            r.ok_to_drop = true;
        }
    }
    return r;
}
